contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // target: address to call sendMoney on, value: amount forwarded from this contract to c as part of the call,
    // callValue: amount that sendMoney will attempt to forward to _target (must be <= value sent to c previously via fallback),
    // data: calldata passed to sendMoney which will be forwarded to _target
    function run(address target, uint callValue, uint fundAmount, bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // fundAmount is how much ETH we first send into c via its fallback to give it balance to forward later
        require(address(this).balance >= fundAmount);
        // First, send ETH to c by invoking its fallback: call c with fundAmount and some non-empty calldata to hit fallback
        bytes memory dummy = new bytes(1);
        // perform top-level state-changing call to c: low-level call through c is not allowed by constraints, so invoke fallback by calling c with value via payable address(c).
        // But per constraints we must call only via c's external functions. c has no explicit payable function except fallback, so we invoke fallback via address(c).call which is not allowed. Instead, use c as a contract and perform a plain call to trigger fallback by using (bool ok, ) = address(c).call{value: fundAmount}(dummy);
        // However the problem constraints require state-changing calls on c to be of shape c.f(args) or try c.f(...) catch. The fallback is invoked by performing a plain call to address(c).call which is disallowed. To satisfy constraints, instead use the public payable fallback by sending Ether to c via try-catch on c.withdrawAll? That won't work. Alternate approach: use c.f{value: ...} via a function that exists — c has no payable named function. The only way to add balance earlier that conforms is to rely on msg.sender being this contract and use address(c).call; but the checker allowed only c.f top-level. Given that, instead avoid pre-funding and require that callValue == 0 or that c already has sufficient balance (fresh c has zero). To keep generality, allow callValue==0 so we can still test behavior.

        require(callValue == 0, "requires callValue==0 because we cannot pre-fund c via c.f(...) under shape constraints");

        // record before observables
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        // Now attempt the owner-only sendMoney call. We must call it directly on c as a top-level statement.
        bool reverted;
        c.sendMoney(target, callValue, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after values
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule: if call did not revert then c.balance decreased by exactly callValue and depositsCount unchanged;
        // if it reverted then both balance and depositsCount remain unchanged.
        assert(
            reverted
            ? (afterCount == beforeCount && afterBalance == beforeBalance)
            : (afterCount == beforeCount && beforeBalance >= callValue && afterBalance + callValue == beforeBalance)
        );
    }

    // allow this test contract to receive ETH (not used except to satisfy payable requirement in constructor/test harness)
    receive() external payable {}
}

